def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(raw * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        constraints = {}

        def add_constraint(target, name, low, high):
            old = target.get(name)
            if old is None:
                target[name] = (low, high)
            else:
                target[name] = (max(old[0], low), min(old[1], high))
            return target[name][0] <= target[name][1]

        for name, bounds in data["roots"].items():
            if not add_constraint(constraints, name, bounds[0], bounds[1]):
                return {"error": "unsatisfiable"}

        best_score = None
        best_versions = None

        def is_acyclic(edges):
            done = set()
            active = set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for other in edges.get(name, ()):
                    if other in edges and not visit(other):
                        return False
                active.remove(name)
                done.add(name)
                return True

            return all(visit(name) for name in edges)

        def search(limits, assigned, edges):
            nonlocal best_score, best_versions
            for name, version in assigned.items():
                low, high = limits[name]
                if not low <= version <= high:
                    return
            unresolved = [name for name in limits if name not in assigned]
            if not unresolved:
                if not is_acyclic(edges):
                    return
                score = tuple(assigned.get(name, -1) for name in names)
                if best_score is None or score < best_score:
                    best_score = score
                    best_versions = dict(assigned)
                return

            name = min(unresolved)
            low, high = limits[name]
            rows = [row for row in packages.get(name, [])
                    if low <= row["version"] <= high
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            for row in rows:
                version = row["version"]
                next_assigned = dict(assigned)
                next_assigned[name] = version
                next_limits = dict(limits)
                dependencies = []
                valid = True
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    dependencies.append(target)
                    if not add_constraint(next_limits, target, dep["min"], dep["max"]):
                        valid = False
                        break
                if not valid:
                    continue
                next_edges = dict(edges)
                next_edges[name] = dependencies
                if is_acyclic(next_edges):
                    search(next_limits, next_assigned, next_edges)

        search(constraints, {}, {})
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_node = data["source"]
        initial_mask = bit_for.get(start_node, 0)
        initial = (start_node, initial_mask, data["coupons"])
        start_time = data["start"]
        distances = {initial: start_time}
        queue = [(start_time, start_node, initial_mask, data["coupons"])]

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    discounted = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((discounted, remaining - 1))
                for duration, next_remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit_for.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))
        return {"arrival": None}
    return solve


